(self.webpackChunksite=self.webpackChunksite||[]).push([[9572],{6216:t=>{"use strict";t.exports=JSON.parse('{"slug":"raycast-maze","title":"Raycast Maze","authors":[{"name":"Bruno Rafael Comin Scheffel","contact":"brsctoo","contactType":"github","contactUrl":"https://github.com/brsctoo"},{"name":"Jos\xe9 Luis Peres de Sousa","contact":null,"contactType":null,"contactUrl":null}],"date":1782864000000,"readme":"<p>Find the exit before the timer runs out! A first-person maze game\\nbuilt with a raycasting engine, running on the WASM-4 fantasy console.</p>\\n<h2>How to play</h2>\\n<p>Navigate a 3D maze from a first-person view and reach the exit\\n(the blinking wall) before the countdown hits zero.</p>\\n<ul>\\n<li><strong>Arrow Up / Down</strong>: Move forward / backward</li>\\n<li><strong>Arrow Left / Right</strong>: Turn left / right</li>\\n<li><strong>X</strong>: Start the game / confirm</li>\\n<li><strong>Z</strong>: Return to the main menu (during gameplay)</li>\\n</ul>\\n<h2>Features</h2>\\n<ul>\\n<li>Real-time raycasting engine (Wolfenstein-style 3D)</li>\\n<li>Three difficulty levels (Easy, Medium, Hard) with larger, denser 32x32 mazes and their own time limits</li>\\n<li>Linked portal pair: step into one portal to teleport across the maze, shown with a glitchy animated wall</li>\\n<li>A compass that always points north to help you stay oriented</li>\\n<li>A countdown timer and sound effects for menus, steps, and events</li>\\n</ul>\\n<h2>Tips</h2>\\n<p>Use the compass in the top-right corner to keep track of direction.\\nThe two portals are a shortcut across the map \u2014 find them to save\\ntime on the harder mazes. On Hard, the layout is denser and larger,\\nso plan your route and watch the clock.</p>"}')}}]);